<script lang="ts">import { signOut } from '$lib/api'; let email=$state(true), counselling=$state(true); async function logout(){await signOut();window.location.assign('/login')}</script><div class="max-w-3xl space-y-6"><div><h1 class="text-3xl font-bold text-white">Settings</h1><p class="text-text-secondary mt-2">Manage account, notification and security preferences.</p></div><div class="bg-card border border-white/10 rounded-2xl divide-y divide-white/10"><section><div><h2>Account</h2><p>Update your personal and admission preferences.</p></div><a href="/student/profile" class="text-accent text-sm">Profile settings →</a></section><section><div><h2>Notification Preferences</h2><p>Receive email updates about your admission journey.</p></div><input type="checkbox" bind:checked={email}/></section><section><div><h2>Counselling Updates</h2><p>Receive appointment and follow-up reminders.</p></div><input type="checkbox" bind:checked={counselling}/></section><section><div><h2>Security</h2><p>Change your password securely.</p></div><button class="secondary">Change Password</button></section><section><div><h2>Session</h2><p>Sign out from this device.</p></div><button onclick={logout} class="logout">Logout</button></section></div></div><style>section{padding:1.25rem 1.5rem;display:flex;align-items:center;justify-content:space-between;gap:1rem}h2{color:white;font-weight:600;font-size:.95rem}p{color:#a7a4b4;font-size:.8rem;margin-top:.25rem}.secondary,.logout{font-size:.8rem;padding:.5rem .75rem;border-radius:.55rem}.secondary{border:1px solid rgba(255,255,255,.12);color:white}.logout{color:#fca5a5;border:1px solid rgba(248,113,113,.3)}</style>
